import{A as e,E as t,d as n,f as r,l as i,p as a,s as o}from"./runtime-core.esm-bundler-tCF-J6l5.js";import{t as s}from"./app-DgnfxEif.js";var c=JSON.parse(`{"path":"/Linux/07_Nginx/05_SSL_TLS%E4%B8%8EHTTPS/01_SSL_TLS%E6%8F%A1%E6%89%8B%E5%8E%9F%E7%90%86.html","title":"SSL/TLS 握手原理","lang":"zh-CN","frontmatter":{"title":"SSL/TLS 握手原理","icon":"fa6-solid:handshake","order":1,"category":["Linux","Nginx"],"tag":["SSL","TLS","HTTPS","握手","密码套件"]},"git":{"createdTime":1780631738000,"updatedTime":1780712648000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":23.77,"words":7131},"filePathRelative":"Linux/07_Nginx/05_SSL_TLS与HTTPS/01_SSL_TLS握手原理.md"}`),l={name:`01_SSL_TLS握手原理.md`};function u(s,c,l,u,d,f){let p=e(`Mermaid`);return t(),i(`div`,null,[c[0]||=o(`h1`,{id:`ssl-tls-握手原理`,tabindex:`-1`},[o(`a`,{class:`header-anchor`,href:`#ssl-tls-握手原理`},[o(`span`,null,`SSL/TLS 握手原理`)])],-1),c[1]||=o(`h2`,{id:`从-http-到-https-的演进`,tabindex:`-1`},[o(`a`,{class:`header-anchor`,href:`#从-http-到-https-的演进`},[o(`span`,null,`从 HTTP 到 HTTPS 的演进`)])],-1),c[2]||=o(`p`,null,[r(`HTTP 协议以明文方式传输数据，这意味着在客户端与服务器之间的任何中间人都可以窃听、篡改通信内容。SSL/TLS 协议的引入正是为了在传输层之上构建加密通道，实现数据的`),o(`strong`,null,`机密性`),r(`、`),o(`strong`,null,`完整性`),r(`和`),o(`strong`,null,`身份认证`),r(`。`)],-1),a(p,{code:`eJxLy8kvT85ILCpR8AniUgACx2iPkJAAhWcz+p5Na3+yZ8GLfZNjFXR17RScooODfRSedi14ur7tZcOsl42TY8EanMCyzmBtwQpP13U+bV0B1QeWdwbLu0Q/m7MLqPNZw3IF5/y8tMyU1LySzMSczJJKZGWu0U/X9TybugWkzDOvJDW9CE2BW/SLXauf7N77Yt2SF+sbFRxLSzJABiUnlmTm58VyAQBrw1Wo`}),c[3]||=n(`<p>HTTPS 并非一个独立的协议，而是 HTTP over TLS 的组合：HTTP 负责应用层通信，TLS 负责加密与安全。在 Nginx 中，TLS 由 <code>ngx_http_ssl_module</code> 模块提供支持，底层依赖 OpenSSL 库。</p><div class="hint-container tip"><p class="hint-container-title">术语区分</p><ul><li><strong>SSL</strong>（Secure Sockets Layer）：由 Netscape 提出，已废弃</li><li><strong>TLS</strong>（Transport Layer Security）：SSL 的继任者，IETF 标准化</li><li>日常说&quot;SSL证书&quot;实际指 TLS 证书，多数工具和配置仍沿用 SSL 命名</li></ul></div><hr><h2 id="ssl-tls-发展历史" tabindex="-1"><a class="header-anchor" href="#ssl-tls-发展历史"><span>SSL/TLS 发展历史</span></a></h2><p>SSL/TLS 协议经历了多次迭代，每次版本升级都带来了安全性与性能的改进：</p><table><thead><tr><th>版本</th><th>年份</th><th>状态</th><th>关键改进</th></tr></thead><tbody><tr><td>SSLv1</td><td>1994</td><td>从未发布</td><td>原型，存在严重缺陷</td></tr><tr><td>SSLv2</td><td>1995</td><td>已废弃</td><td>首个公开版本，存在中间人攻击漏洞</td></tr><tr><td>SSLv3</td><td>1996</td><td>已废弃</td><td>添加了密钥交换改进，但存在 POODLE 攻击</td></tr><tr><td>TLS 1.0</td><td>1999</td><td>已废弃</td><td>IETF 标准化（RFC 2246），实质是 SSLv3.1</td></tr><tr><td>TLS 1.1</td><td>2006</td><td>已废弃</td><td>添加 CBC 攻击防护（RFC 4346）</td></tr><tr><td>TLS 1.2</td><td>2008</td><td>广泛使用</td><td>支持 AEAD 加密（RFC 5246），当前主流版本</td></tr><tr><td>TLS 1.3</td><td>2018</td><td>推荐使用</td><td>1-RTT 握手、0-RTT 恢复、移除不安全算法（RFC 8446）</td></tr></tbody></table>`,6),a(p,{code:`eJwrycxNzcnMS+VSAIKSzJKcVIXgYB/9EJ9ghaf9E59unPps+raX07c837UfrMLQ0tJEwQqkpMwQSD+bswqkakczTNIUKmkEpF8um/Zkx6qnrWue7ml43tnxbM4amCozqCpjkBFTdr7YP/vp+raXk5Y+2bXkWe8imCpLoCzIHYZ6BkCWp2uIm8KzBe1P29ue9kwDqzEyMACZBFEDco6zkzPQvN1P23e/nLHpWdcSmCoLuCqQuxxdHV0UnnYtANr5bMr6Zz2NUGWGCGUghxnqBoWEKOgrGIBoLgALVWxu`}),c[4]||=n(`<div class="hint-container warning"><p class="hint-container-title">已废弃协议</p><p>SSLv2、SSLv3、TLS 1.0、TLS 1.1 均已被 IETF 正式废弃（RFC 8996）。这些协议存在已知安全漏洞：</p><ul><li><strong>POODLE</strong>（Padding Oracle On Downgraded Legacy Encryption）：针对 SSLv3</li><li><strong>BEAST</strong>（Browser Exploit Against SSL/TLS）：针对 TLS 1.0</li><li><strong>RC4 偏差攻击</strong>：针对使用 RC4 的早期 TLS</li></ul></div><h3 id="版本协商机制" tabindex="-1"><a class="header-anchor" href="#版本协商机制"><span>版本协商机制</span></a></h3><p>客户端与服务器在握手阶段协商使用的 TLS 版本。TLS 1.3 引入了全新的版本协商方式：</p><ul><li><strong>TLS 1.2 及更早</strong>：通过 <code>ClientHello.client_version</code> 字段协商，容易遭受协议降级攻击</li><li><strong>TLS 1.3</strong>：使用 <code>supported_versions</code> 扩展进行协商，并引入 <code>downgrade_sentinel</code> 防止降级攻击</li></ul><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span># TLS 1.2 版本协商</span></span>
<span class="line"><span>ClientHello: client_version = TLS 1.2</span></span>
<span class="line"><span>ServerHello: server_version = TLS 1.2 (选择双方支持的最高版本)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># TLS 1.3 版本协商</span></span>
<span class="line"><span>ClientHello: supported_versions = [TLS 1.3, TLS 1.2]</span></span>
<span class="line"><span>ServerHello: supported_versions = TLS 1.3</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="tls-1-2-握手完整流程" tabindex="-1"><a class="header-anchor" href="#tls-1-2-握手完整流程"><span>TLS 1.2 握手完整流程</span></a></h2><p>TLS 1.2 的完整握手需要 <strong>2 个 RTT</strong>（Round-Trip Time），是理解 TLS 工作原理的基础。</p>`,8),a(p,{code:``}),c[5]||=n(`<h3 id="clienthello-详解" tabindex="-1"><a class="header-anchor" href="#clienthello-详解"><span>ClientHello 详解</span></a></h3><p>ClientHello 是握手的第一步，客户端向服务器发送以下信息：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 在 Nginx 中可配置客户端支持的协议和密码套件</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_protocols</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"><span style="color:#C678DD;">ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ClientHello 包含的关键字段：</p><table><thead><tr><th>字段</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>client_version</td><td>客户端支持的最高 TLS 版本</td><td>TLS 1.2 (0x0303)</td></tr><tr><td>random</td><td>32 字节随机数 Rc</td><td>随机生成，用于密钥推导</td></tr><tr><td>session_id</td><td>会话 ID（空表示新会话）</td><td>0 字节或 32 字节</td></tr><tr><td>cipher_suites</td><td>客户端支持的密码套件列表</td><td>按优先级排列</td></tr><tr><td>compression_methods</td><td>压缩方法列表</td><td>通常为 null</td></tr><tr><td>extensions</td><td>扩展字段</td><td>SNI、ALPN、signature_algorithms 等</td></tr></tbody></table><div class="hint-container important"><p class="hint-container-title">随机数的作用</p><p>ClientHello 和 ServerHello 中的随机数（Rc、Rs）是密钥推导的关键输入。它们确保每次握手生成的密钥都不同，即使使用相同的预主密钥（Pre-Master Secret），也能产生不同的主密钥（Master Secret），有效防止重放攻击。</p></div><h3 id="serverhello-详解" tabindex="-1"><a class="header-anchor" href="#serverhello-详解"><span>ServerHello 详解</span></a></h3><p>服务器从客户端提供的选项中选择一组参数：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>ServerHello {</span></span>
<span class="line"><span>    server_version     = TLS 1.2          // 选择的TLS版本</span></span>
<span class="line"><span>    random             = Rs               // 32字节服务器随机数</span></span>
<span class="line"><span>    session_id         = &lt;session_id&gt;     // 会话ID</span></span>
<span class="line"><span>    cipher_suite       = 0xC02F           // 选择的密码套件</span></span>
<span class="line"><span>    compression_method = 0x00             // null压缩</span></span>
<span class="line"><span>    extensions         = ...              // 服务器扩展</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="certificate-消息" tabindex="-1"><a class="header-anchor" href="#certificate-消息"><span>Certificate 消息</span></a></h3><p>服务器发送其证书链，通常包含：</p><ol><li><strong>服务器证书（End-Entity Certificate）</strong>：包含服务器公钥和域名信息</li><li><strong>中间证书（Intermediate CA Certificate）</strong>：签发服务器证书的 CA</li><li>通常不包含根证书（客户端应已信任根证书）</li></ol><p>证书的 X.509 结构关键字段：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>Certificate {</span></span>
<span class="line"><span>    Version: V3</span></span>
<span class="line"><span>    Serial Number: 01:23:45:67:89:AB:CD:EF</span></span>
<span class="line"><span>    Signature Algorithm: sha256WithRSAEncryption</span></span>
<span class="line"><span>    Issuer: C=US, O=Let&#39;s Encrypt, CN=R3</span></span>
<span class="line"><span>    Validity:</span></span>
<span class="line"><span>        Not Before: Jan 1 00:00:00 2025 GMT</span></span>
<span class="line"><span>        Not After : Apr 1 00:00:00 2025 GMT</span></span>
<span class="line"><span>    Subject: CN=example.com</span></span>
<span class="line"><span>    Subject Public Key Info:</span></span>
<span class="line"><span>        Public Key Algorithm: id-ecPublicKey</span></span>
<span class="line"><span>        EC Public Key: (256 bit)</span></span>
<span class="line"><span>    Extensions:</span></span>
<span class="line"><span>        subjectAltName: DNS:example.com, DNS:*.example.com</span></span>
<span class="line"><span>        authorityInfoAccess: OCSP - URI:http://r3.o.lencr.org</span></span>
<span class="line"><span>        ...</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="serverkeyexchange-与密钥推导" tabindex="-1"><a class="header-anchor" href="#serverkeyexchange-与密钥推导"><span>ServerKeyExchange 与密钥推导</span></a></h3><p>根据密码套件中密钥交换算法的不同，ServerKeyExchange 的内容也不同：</p><p><strong>RSA 密钥交换</strong>：不需要 ServerKeyExchange，预主密钥由客户端生成并使用服务器公钥加密</p><p><strong>DHE 密钥交换</strong>：服务器发送 DH 参数和公钥</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>ServerKeyExchange {</span></span>
<span class="line"><span>    dh_p       = &lt;大素数p&gt;           // DH参数</span></span>
<span class="line"><span>    dh_g       = &lt;生成元g&gt;           // DH参数</span></span>
<span class="line"><span>    dh_Ys      = &lt;服务器DH公钥&gt;      // g^b mod p</span></span>
<span class="line"><span>    signature  = &lt;签名&gt;              // 服务器对参数的签名</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>ECDHE 密钥交换</strong>：服务器发送曲线参数和公钥</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>ServerKeyExchange {</span></span>
<span class="line"><span>    curve_type = named_curve</span></span>
<span class="line"><span>    named_curve = x25519             // 椭圆曲线名称</span></span>
<span class="line"><span>    public_key  = &lt;服务器ECDH公钥&gt;   // 65字节(未压缩格式)</span></span>
<span class="line"><span>    signature   = &lt;签名&gt;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="密钥推导过程" tabindex="-1"><a class="header-anchor" href="#密钥推导过程"><span>密钥推导过程</span></a></h3><p>TLS 1.2 的密钥推导使用 PRF（Pseudo-Random Function）：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span># 预主密钥（Pre-Master Secret）的生成</span></span>
<span class="line"><span># RSA:  客户端生成48字节随机数，用服务器公钥加密</span></span>
<span class="line"><span># DHE:  两者计算共享密钥</span></span>
<span class="line"><span># ECDHE: 两者计算共享密钥</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 主密钥（Master Secret）推导</span></span>
<span class="line"><span>MasterSecret = PRF(PreMasterSecret, &quot;master secret&quot;,</span></span>
<span class="line"><span>                   ClientHello.random + ServerHello.random)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 密钥块（Key Block）推导</span></span>
<span class="line"><span>KeyBlock = PRF(MasterSecret, &quot;key expansion&quot;,</span></span>
<span class="line"><span>               ServerHello.random + ClientHello.random)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 密钥块分割为：</span></span>
<span class="line"><span># client_write_MAC_key[N]    客户端MAC密钥</span></span>
<span class="line"><span># server_write_MAC_key[N]    服务器MAC密钥</span></span>
<span class="line"><span># client_write_key[N]        客户端加密密钥</span></span>
<span class="line"><span># server_write_key[N]        服务器加密密钥</span></span>
<span class="line"><span># client_write_IV[N]         客户端IV</span></span>
<span class="line"><span># server_write_IV[N]         服务器IV</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container info"><p class="hint-container-title">为什么需要两个随机数</p><p>ClientHello.random 和 ServerHello.random 共同参与密钥推导。即使攻击者知道其中一个随机数，只要另一个保持不可预测，生成的密钥就是安全的。两个随机数的组合大大增加了密钥的不可预测性。</p></div><h3 id="changecipherspec-与-finished" tabindex="-1"><a class="header-anchor" href="#changecipherspec-与-finished"><span>ChangeCipherSpec 与 Finished</span></a></h3><p>ChangeCipherSpec 消息通知对方后续消息将使用协商好的加密参数。Finished 消息是第一条加密消息，包含 <code>verify_data</code>，用于验证握手过程未被篡改：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>verify_data = PRF(MasterSecret, finished_label,</span></span>
<span class="line"><span>                  Hash(handshake_messages))</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>其中 <code>handshake_messages</code> 是所有握手消息的拼接哈希，<code>finished_label</code> 对客户端为 <code>&quot;client finished&quot;</code>，对服务器为 <code>&quot;server finished&quot;</code>。</p><hr><h2 id="tls-1-3-握手改进" tabindex="-1"><a class="header-anchor" href="#tls-1-3-握手改进"><span>TLS 1.3 握手改进</span></a></h2><p>TLS 1.3 是对 TLS 协议的重大简化，移除了大量不安全的遗留特性，将握手从 2-RTT 缩短到 1-RTT，并支持 0-RTT 恢复。</p><h3 id="tls-1-3-移除的特性" tabindex="-1"><a class="header-anchor" href="#tls-1-3-移除的特性"><span>TLS 1.3 移除的特性</span></a></h3><table><thead><tr><th>移除的特性</th><th>原因</th></tr></thead><tbody><tr><td>RSA 密钥交换</td><td>不支持前向保密（Forward Secrecy）</td></tr><tr><td>DHE 密钥交换</td><td>效率低于 ECDHE</td></tr><tr><td>CBC 模式加密</td><td>易受 Lucky13 等攻击</td></tr><tr><td>RC4 加密</td><td>已知不安全</td></tr><tr><td>SHA-1 哈希</td><td>碰撞攻击</td></tr><tr><td>MD5 哈希</td><td>已知不安全</td></tr><tr><td>压缩协商</td><td>CRIME 攻击</td></tr><tr><td>renegotiation</td><td>复杂且存在安全漏洞</td></tr><tr><td>非 AEAD 密码套件</td><td>缺乏认证加密</td></tr></tbody></table><h3 id="tls-1-3-的-1-rtt-握手" tabindex="-1"><a class="header-anchor" href="#tls-1-3-的-1-rtt-握手"><span>TLS 1.3 的 1-RTT 握手</span></a></h3>`,35),a(p,{code:``}),c[6]||=n(`<div class="hint-container important"><p class="hint-container-title">核心改进：提前发送密钥共享</p><p>TLS 1.3 的关键优化在于客户端在 ClientHello 中就发送 DH 公钥（key_share 扩展）。服务器收到后可以直接计算出共享密钥，使得 ServerHello 之后的消息全部加密传输。这比 TLS 1.2 节省了一个 RTT。</p></div><h3 id="tls-1-3-密码套件" tabindex="-1"><a class="header-anchor" href="#tls-1-3-密码套件"><span>TLS 1.3 密码套件</span></a></h3><p>TLS 1.3 大幅简化了密码套件，仅保留 5 个：</p><table><thead><tr><th>密码套件</th><th>密钥交换</th><th>认证</th><th>加密</th><th>哈希</th></tr></thead><tbody><tr><td>TLS_AES_128_GCM_SHA256</td><td>ECDHE</td><td>RSA/ECDSA</td><td>AES-128-GCM</td><td>SHA-256</td></tr><tr><td>TLS_AES_256_GCM_SHA384</td><td>ECDHE</td><td>RSA/ECDSA</td><td>AES-256-GCM</td><td>SHA-384</td></tr><tr><td>TLS_CHACHA20_POLY1305_SHA256</td><td>ECDHE</td><td>RSA/ECDSA</td><td>ChaCha20-Poly1305</td><td>SHA-256</td></tr><tr><td>TLS_AES_128_CCM_SHA256</td><td>ECDHE</td><td>RSA/ECDSA</td><td>AES-128-CCM</td><td>SHA-256</td></tr><tr><td>TLS_AES_128_CCM_8_SHA256</td><td>ECDHE</td><td>RSA/ECDSA</td><td>AES-128-CCM-8</td><td>SHA-256</td></tr></tbody></table><p>在 Nginx 中配置 TLS 1.3 密码套件：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_ciphers</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># TLS 1.3 密码套件配置（OpenSSL 1.1.1+）</span></span>
<span class="line"><span style="color:#C678DD;">ssl_ciphers </span><span style="color:#98C379;">&#39;TLS_AES_128_GCM_SHA256:TLS_AES_256_GCM_SHA384:TLS_CHACHA20_POLY1305_SHA256&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># TLS 1.3 的密码套件用冒号分隔，与 TLS 1.2 语法一致</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 但实际 TLS 1.3 密码套件是独立协商的，不受 ssl_ciphers 顺序影响</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="tls-1-3-的-0-rtt-恢复" tabindex="-1"><a class="header-anchor" href="#tls-1-3-的-0-rtt-恢复"><span>TLS 1.3 的 0-RTT 恢复</span></a></h3><p>当客户端之前与服务器建立过 TLS 1.3 连接时，可以使用 PSK（Pre-Shared Key）实现 0-RTT 恢复：</p>`,8),a(p,{code:``}),c[7]||=n(`<div class="hint-container warning"><p class="hint-container-title">0-RTT 的安全风险</p><p>0-RTT 数据容易遭受<strong>重放攻击</strong>，因为攻击者可以截获 0-RTT 数据并重新发送。以下操作不应通过 0-RTT 发送：</p><ul><li>非幂等操作（如 POST 请求）</li><li>状态修改操作（如支付、转账）</li><li>任何具有副作用的请求</li></ul><p>Nginx 默认不启用 0-RTT，需要显式配置 <code>ssl_early_data on;</code>。</p></div><h3 id="tls-1-3-密钥推导" tabindex="-1"><a class="header-anchor" href="#tls-1-3-密钥推导"><span>TLS 1.3 密钥推导</span></a></h3><p>TLS 1.3 使用 HKDF（HMAC-based Key Derivation Function）替代了 TLS 1.2 的 PRF：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span># TLS 1.3 密钥推导层次</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Early Secret ──→ early_exporter_master_secret</span></span>
<span class="line"><span>             ──→ client_early_traffic_secret</span></span>
<span class="line"><span></span></span>
<span class="line"><span>           Handshake Secret ──→ client_handshake_traffic_secret</span></span>
<span class="line"><span>                           ──→ server_handshake_traffic_secret</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                      Master Secret ──→ client_application_traffic_secret</span></span>
<span class="line"><span>                                   ──→ server_application_traffic_secret</span></span>
<span class="line"><span>                                   ──→ exporter_master_secret</span></span>
<span class="line"><span>                                   ──→ resumption_master_secret</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>每一层密钥独立推导，实现了密钥隔离（Key Separation），即使某一层密钥泄露也不会影响其他层。</p><h3 id="nginx-启用-tls-1-3" tabindex="-1"><a class="header-anchor" href="#nginx-启用-tls-1-3"><span>Nginx 启用 TLS 1.3</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_protocols</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 启用 TLS 1.3（需要 OpenSSL 1.1.1+）</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # TLS 1.3 early data（0-RTT），默认 off</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 谨慎启用，存在重放攻击风险</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_early_data </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 0-RTT 请求携带此头部，后端可据此判断</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Early-Data $</span><span style="color:#E06C75;">ssl_early_data</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>检查当前 Nginx 是否支持 TLS 1.3：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 检查 OpenSSL 版本</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> version</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 需要 OpenSSL 1.1.1 或更高</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查 Nginx 编译参数</span></span>
<span class="line"><span style="color:#61AFEF;">nginx</span><span style="color:#D19A66;"> -V</span><span style="color:#ABB2BF;"> 2&gt;&amp;1 | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -o</span><span style="color:#98C379;"> &#39;ssl.*&#39;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 确认包含 --with-http_ssl_module</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 TLS 1.3 连接</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_3</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="密码套件-cipher-suite" tabindex="-1"><a class="header-anchor" href="#密码套件-cipher-suite"><span>密码套件（Cipher Suite）</span></a></h2><p>密码套件定义了 TLS 连接使用的加密算法组合，是 TLS 安全的核心。</p><h3 id="密码套件的命名规则" tabindex="-1"><a class="header-anchor" href="#密码套件的命名规则"><span>密码套件的命名规则</span></a></h3><p>以 <code>TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256</code> 为例：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>TLS _ ECDHE _ RSA _ WITH _ AES_128_GCM _ SHA256</span></span>
<span class="line"><span> │      │       │       │        │           │</span></span>
<span class="line"><span> │      │       │       │        │           └─ PRF/HMAC算法</span></span>
<span class="line"><span> │      │       │       │        └─ 对称加密算法与模式</span></span>
<span class="line"><span> │      │       │       └─ 分隔符</span></span>
<span class="line"><span> │      │       └─ 身份认证算法</span></span>
<span class="line"><span> │      └─ 密钥交换算法</span></span>
<span class="line"><span> └─ 协议标识</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TLS 1.3 密码套件命名简化了（密钥交换和认证不再包含在套件名中）：</span></span>
<span class="line"><span>TLS_AES_128_GCM_SHA256</span></span>
<span class="line"><span> └─ 对称加密 + 哈希</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="密码套件四大组成部分" tabindex="-1"><a class="header-anchor" href="#密码套件四大组成部分"><span>密码套件四大组成部分</span></a></h3>`,16),a(p,{code:``}),c[8]||=n(`<div class="hint-container tip"><p class="hint-container-title">TLS 1.3 的简化</p><p>TLS 1.3 的密码套件不再包含密钥交换和认证算法，因为这些由单独的扩展协商。TLS 1.3 密码套件只指定对称加密和哈希算法。</p></div><h3 id="常见密码套件对比" tabindex="-1"><a class="header-anchor" href="#常见密码套件对比"><span>常见密码套件对比</span></a></h3><table><thead><tr><th>密码套件</th><th>密钥交换</th><th>认证</th><th>加密</th><th>MAC</th><th>前向保密</th><th>安全等级</th></tr></thead><tbody><tr><td>TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256</td><td>ECDHE</td><td>RSA</td><td>AES-128-GCM</td><td>SHA-256</td><td>是</td><td>推荐</td></tr><tr><td>TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384</td><td>ECDHE</td><td>RSA</td><td>AES-256-GCM</td><td>SHA-384</td><td>是</td><td>推荐</td></tr><tr><td>TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305_SHA256</td><td>ECDHE</td><td>RSA</td><td>ChaCha20-Poly1305</td><td>SHA-256</td><td>是</td><td>推荐</td></tr><tr><td>TLS_RSA_WITH_AES_128_GCM_SHA256</td><td>RSA</td><td>RSA</td><td>AES-128-GCM</td><td>SHA-256</td><td>否</td><td>不推荐</td></tr><tr><td>TLS_RSA_WITH_AES_256_CBC_SHA</td><td>RSA</td><td>RSA</td><td>AES-256-CBC</td><td>SHA-1</td><td>否</td><td>弃用</td></tr></tbody></table><hr><h2 id="密钥交换算法" tabindex="-1"><a class="header-anchor" href="#密钥交换算法"><span>密钥交换算法</span></a></h2><p>密钥交换算法决定了客户端和服务器如何安全地协商出共享的对称密钥。</p><h3 id="rsa-密钥交换" tabindex="-1"><a class="header-anchor" href="#rsa-密钥交换"><span>RSA 密钥交换</span></a></h3><p>RSA 密钥交换是最古老的方式，已被 TLS 1.3 移除：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 客户端获取服务器证书中的 RSA 公钥</span></span>
<span class="line"><span>2. 客户端生成 48 字节的预主密钥（Pre-Master Secret）</span></span>
<span class="line"><span>3. 客户端用服务器公钥加密预主密钥</span></span>
<span class="line"><span>4. 服务器用私钥解密，获得预主密钥</span></span>
<span class="line"><span>5. 双方基于预主密钥推导主密钥</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>致命缺陷</strong>：不支持前向保密（Forward Secrecy）。如果服务器私钥泄露，所有历史通信都可被解密。</p><div class="hint-container warning"><p class="hint-container-title">前向保密（Forward Secrecy）</p><p>前向保密是指长期密钥泄露不会导致历史会话密钥泄露。实现前向保密的关键是：每次会话使用临时的（ephemeral）密钥对进行密钥交换，而非使用长期私钥直接加密。</p></div><h3 id="dhe-密钥交换" tabindex="-1"><a class="header-anchor" href="#dhe-密钥交换"><span>DHE 密钥交换</span></a></h3><p>Diffie-Hellman Ephemeral 密钥交换提供前向保密：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 服务器生成 DH 参数 (p, g) 和临时私钥 b，计算 Ys = g^b mod p</span></span>
<span class="line"><span>2. 客户端生成临时私钥 a，计算 Yc = g^a mod p</span></span>
<span class="line"><span>3. 双方交换公钥：客户端发送 Yc，服务器发送 Ys</span></span>
<span class="line"><span>4. 双方计算共享密钥：</span></span>
<span class="line"><span>   - 客户端：K = Ys^a mod p = g^(ab) mod p</span></span>
<span class="line"><span>   - 服务器：K = Yc^b mod p = g^(ab) mod p</span></span>
<span class="line"><span>5. 临时密钥 a, b 在会话结束后销毁</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优点</strong>：支持前向保密<br><strong>缺点</strong>：计算量大（大素数模运算），握手延迟高</p><h3 id="ecdhe-密钥交换" tabindex="-1"><a class="header-anchor" href="#ecdhe-密钥交换"><span>ECDHE 密钥交换</span></a></h3><p>Elliptic Curve Diffie-Hellman Ephemeral 是当前推荐的密钥交换方式：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 服务器选择椭圆曲线和临时密钥对 (dS, QS)，QS = dS × G</span></span>
<span class="line"><span>2. 客户端选择临时密钥对 (dC, QC)，QC = dC × G</span></span>
<span class="line"><span>3. 双方交换公钥点 QS 和 QC</span></span>
<span class="line"><span>4. 双方计算共享密钥：</span></span>
<span class="line"><span>   - 客户端：K = dC × QS = dC × dS × G</span></span>
<span class="line"><span>   - 服务器：K = dS × QC = dS × dC × G</span></span>
<span class="line"><span>5. 临时密钥在会话结束后销毁</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>支持的曲线</strong>：</p><table><thead><tr><th>曲线名称</th><th>密钥长度</th><th>安全等级</th><th>性能</th><th>推荐</th></tr></thead><tbody><tr><td>X25519</td><td>256 bit</td><td>~128 bit</td><td>优秀</td><td>推荐</td></tr><tr><td>secp256r1 (P-256)</td><td>256 bit</td><td>~128 bit</td><td>良好</td><td>可用</td></tr><tr><td>secp384r1 (P-384)</td><td>384 bit</td><td>~192 bit</td><td>较慢</td><td>特殊需求</td></tr><tr><td>X448</td><td>448 bit</td><td>~224 bit</td><td>较慢</td><td>特殊需求</td></tr></tbody></table><p>在 Nginx 中配置 ECDHE 曲线：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_ecdh_curve</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 优先使用 X25519</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ecdh_curve </span><span style="color:#ABB2BF;">X25519:secp256r1:secp384r1;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="三种密钥交换算法对比" tabindex="-1"><a class="header-anchor" href="#三种密钥交换算法对比"><span>三种密钥交换算法对比</span></a></h3><table><thead><tr><th>特性</th><th>RSA</th><th>DHE</th><th>ECDHE</th></tr></thead><tbody><tr><td>前向保密</td><td>否</td><td>是</td><td>是</td></tr><tr><td>密钥长度</td><td>2048+ bit</td><td>2048+ bit</td><td>256 bit</td></tr><tr><td>计算性能</td><td>快（仅客户端加密）</td><td>慢</td><td>快</td></tr><tr><td>握手延迟</td><td>1-RTT</td><td>2-RTT</td><td>2-RTT (TLS 1.2)</td></tr><tr><td>TLS 1.3</td><td>不支持</td><td>不支持</td><td>唯一选择</td></tr><tr><td>安全性</td><td>低（无FS）</td><td>中</td><td>高</td></tr></tbody></table><hr><h2 id="对称加密算法" tabindex="-1"><a class="header-anchor" href="#对称加密算法"><span>对称加密算法</span></a></h2><p>密钥交换完成后，后续通信使用对称加密算法，其性能远优于非对称加密。</p><h3 id="aes-gcm" tabindex="-1"><a class="header-anchor" href="#aes-gcm"><span>AES-GCM</span></a></h3><p>AES（Advanced Encryption Standard）搭配 GCM（Galois/Counter Mode）模式，是目前最广泛使用的 AEAD 加密：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>AES-GCM 工作原理：</span></span>
<span class="line"><span>1. 计数器模式（CTR）：将 AES 块加密转换为流加密</span></span>
<span class="line"><span>2. 伽罗瓦域乘法（GHASH）：提供认证标签</span></span>
<span class="line"><span>3. 同时提供加密和完整性验证</span></span>
<span class="line"><span></span></span>
<span class="line"><span>加密过程：</span></span>
<span class="line"><span>nonce ──→ IV 构造</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>     AES-CTR ──→ 密文</span></span>
<span class="line"><span>         ↓</span></span>
<span class="line"><span>     GHASH  ──→ 认证标签 Tag</span></span>
<span class="line"><span></span></span>
<span class="line"><span>解密过程：</span></span>
<span class="line"><span>密文 + Tag ──→ 验证 Tag</span></span>
<span class="line"><span>              ↓ 通过</span></span>
<span class="line"><span>           AES-CTR ──→ 明文</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>AES-GCM 变体</strong>：</p><table><thead><tr><th>变体</th><th>密钥长度</th><th>安全等级</th><th>性能</th><th>硬件加速</th></tr></thead><tbody><tr><td>AES-128-GCM</td><td>128 bit</td><td>128 bit</td><td>快</td><td>AES-NI</td></tr><tr><td>AES-256-GCM</td><td>256 bit</td><td>256 bit</td><td>稍慢</td><td>AES-NI</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">AES-NI 硬件加速</p><p>现代 x86 处理器提供 AES-NI 指令集，可将 AES-GCM 性能提升 10-50 倍。检查 CPU 是否支持：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># Linux</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -o</span><span style="color:#98C379;"> aes</span><span style="color:#98C379;"> /proc/cpuinfo</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在 Nginx 中，OpenSSL 自动利用 AES-NI</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> speed</span><span style="color:#98C379;"> aes-128-gcm</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> speed</span><span style="color:#98C379;"> aes-256-gcm</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><h3 id="chacha20-poly1305" tabindex="-1"><a class="header-anchor" href="#chacha20-poly1305"><span>ChaCha20-Poly1305</span></a></h3><p>ChaCha20-Poly1305 是由 Google 推广的 AEAD 加密算法，特别适合没有 AES-NI 硬件加速的设备（如手机、IoT 设备）：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>ChaCha20-Poly1305 工作原理：</span></span>
<span class="line"><span>1. ChaCha20 流密码：生成密钥流</span></span>
<span class="line"><span>2. Poly1305 MAC：生成认证标签</span></span>
<span class="line"><span>3. 同样是 AEAD，提供加密+认证</span></span>
<span class="line"><span></span></span>
<span class="line"><span>优势：</span></span>
<span class="line"><span>- 纯软件实现性能优秀（约 AES-GCM 的 2-3 倍，无 AES-NI 时）</span></span>
<span class="line"><span>- 常数时间实现，无时序攻击风险</span></span>
<span class="line"><span>- 256 bit 密钥，安全强度足够</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>性能对比</strong>（无 AES-NI 的 ARM 设备）：</p><table><thead><tr><th>算法</th><th>加密速度</th><th>认证速度</th><th>总体</th></tr></thead><tbody><tr><td>AES-128-GCM</td><td>200 MB/s</td><td>200 MB/s</td><td>200 MB/s</td></tr><tr><td>ChaCha20-Poly1305</td><td>500 MB/s</td><td>500 MB/s</td><td>500 MB/s</td></tr></tbody></table><p>在 Nginx 中优先使用 ChaCha20：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_ciphers</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 同时支持 AES-GCM 和 ChaCha20，让客户端根据能力选择</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 优先使用服务器端密码套件顺序</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_prefer_server_ciphers </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="aead-与非-aead-对比" tabindex="-1"><a class="header-anchor" href="#aead-与非-aead-对比"><span>AEAD 与非 AEAD 对比</span></a></h3><table><thead><tr><th>特性</th><th>AEAD (GCM/CCM/Poly1305)</th><th>非 AEAD (CBC+HMAC)</th></tr></thead><tbody><tr><td>加密+认证</td><td>一体化</td><td>分开处理</td></tr><tr><td>安全性</td><td>高</td><td>中（Lucky13 等攻击）</td></tr><tr><td>性能</td><td>更好</td><td>较差</td></tr><tr><td>实现复杂度</td><td>简单</td><td>复杂（需正确处理MAC-then-Encrypt）</td></tr><tr><td>TLS 1.3</td><td>必须</td><td>不支持</td></tr></tbody></table><hr><h2 id="证书验证链与-ca-体系" tabindex="-1"><a class="header-anchor" href="#证书验证链与-ca-体系"><span>证书验证链与 CA 体系</span></a></h2><p>TLS 握手中，服务器发送证书后，客户端需要验证证书的合法性，这依赖于 PKI（Public Key Infrastructure）信任链。</p><h3 id="pki-信任体系" tabindex="-1"><a class="header-anchor" href="#pki-信任体系"><span>PKI 信任体系</span></a></h3>`,46),a(p,{code:``}),c[9]||=n(`<h3 id="证书验证流程" tabindex="-1"><a class="header-anchor" href="#证书验证流程"><span>证书验证流程</span></a></h3><p>客户端验证证书的完整流程：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 证书链构建</span></span>
<span class="line"><span>   - 从终端证书开始</span></span>
<span class="line"><span>   - 通过 Authority Information Access (AIA) 扩展或本地缓存获取中间证书</span></span>
<span class="line"><span>   - 递归到根证书</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 签名验证</span></span>
<span class="line"><span>   - 用签发者公钥验证证书签名</span></span>
<span class="line"><span>   - 逐级验证直到根证书</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 有效期检查</span></span>
<span class="line"><span>   - Not Before ≤ 当前时间 ≤ Not After</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 吊销检查</span></span>
<span class="line"><span>   - CRL (Certificate Revocation List)</span></span>
<span class="line"><span>   - OCSP (Online Certificate Status Protocol)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5. 用途检查</span></span>
<span class="line"><span>   - Key Usage 和 Extended Key Usage 扩展</span></span>
<span class="line"><span>   - 确保证书用于 TLS 服务器认证</span></span>
<span class="line"><span></span></span>
<span class="line"><span>6. 域名匹配</span></span>
<span class="line"><span>   - Subject Alternative Name (SAN) 扩展</span></span>
<span class="line"><span>   - Common Name (CN, 已弃用)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="证书链配置" tabindex="-1"><a class="header-anchor" href="#证书链配置"><span>证书链配置</span></a></h3><p>在 Nginx 中，必须正确配置完整的证书链：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_certificate</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 证书文件应包含：终端证书 + 中间证书</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 不要包含根证书</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 私钥文件</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">证书链文件顺序</p><p>证书链文件中的顺序至关重要，必须从终端证书开始，逐级向上：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>-----BEGIN CERTIFICATE-----</span></span>
<span class="line"><span>终端证书 (example.com)</span></span>
<span class="line"><span>-----END CERTIFICATE-----</span></span>
<span class="line"><span>-----BEGIN CERTIFICATE-----</span></span>
<span class="line"><span>中间证书 (R3 / Let&#39;s Encrypt)</span></span>
<span class="line"><span>-----END CERTIFICATE-----</span></span>
<span class="line"><span>-----BEGIN CERTIFICATE-----</span></span>
<span class="line"><span>中间证书 (ISRG Root X1)     ← 可选，部分客户端需要</span></span>
<span class="line"><span>-----END CERTIFICATE-----</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>错误顺序会导致部分客户端无法验证证书链。</p></div><p>创建正确的证书链文件：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 方法 1：使用 cat 拼接</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> example.com.crt</span><span style="color:#98C379;"> intermediate.crt</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">fullchain.pem</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方法 2：使用 certbot 自动生成（推荐）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># certbot 生成的 fullchain.pem 已包含完整链</span></span>
<span class="line"><span style="color:#61AFEF;">ls</span><span style="color:#98C379;"> /etc/letsencrypt/live/example.com/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># cert.pem        - 终端证书</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># chain.pem       - 中间证书</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># fullchain.pem   - 完整证书链</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># privkey.pem     - 私钥</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 验证证书链</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> verify</span><span style="color:#D19A66;"> -CAfile</span><span style="color:#98C379;"> chain.pem</span><span style="color:#98C379;"> cert.pem</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># cert.pem: OK</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看证书链</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -showcerts</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="根证书信任存储" tabindex="-1"><a class="header-anchor" href="#根证书信任存储"><span>根证书信任存储</span></a></h3><p>操作系统和浏览器维护各自的根证书信任存储：</p><table><thead><tr><th>平台</th><th>信任存储位置</th></tr></thead><tbody><tr><td>Linux (Debian/Ubuntu)</td><td><code>/etc/ssl/certs/</code></td></tr><tr><td>Linux (RHEL/CentOS)</td><td><code>/etc/pki/ca-trust/</code></td></tr><tr><td>macOS</td><td>系统钥匙串 Keychain</td></tr><tr><td>Windows</td><td>Windows Certificate Store</td></tr><tr><td>Firefox</td><td>内置 <code>cert9.db</code></td></tr><tr><td>Chrome</td><td>使用系统信任存储</td></tr></tbody></table><hr><h2 id="session-恢复机制" tabindex="-1"><a class="header-anchor" href="#session-恢复机制"><span>Session 恢复机制</span></a></h2><p>完整 TLS 握手开销较大（尤其是 TLS 1.2 的 2-RTT），Session 恢复机制允许客户端和服务器复用之前协商的安全参数，避免重复握手。</p><h3 id="session-id" tabindex="-1"><a class="header-anchor" href="#session-id"><span>Session ID</span></a></h3><p>最古老的 Session 恢复方式：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 首次握手时，服务器在 ServerHello 中返回 session_id</span></span>
<span class="line"><span>2. 服务器在本地缓存该会话的密钥信息</span></span>
<span class="line"><span>3. 客户端下次连接时，在 ClientHello 中携带 session_id</span></span>
<span class="line"><span>4. 服务器查找到对应会话，直接恢复加密通信</span></span>
<span class="line"><span>5. 恢复握手仅需 1-RTT</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>缺点</strong>：</p><ul><li>服务器必须维护会话缓存，内存开销大</li><li>多服务器环境下需要共享缓存（Session Cache 共享）</li><li>不适合大规模部署</li></ul><h3 id="session-ticket" tabindex="-1"><a class="header-anchor" href="#session-ticket"><span>Session Ticket</span></a></h3><p>Session Ticket 方案解决了 Session ID 的服务器端存储问题：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 首次握手完成后，服务器发送 NewSessionTicket 消息</span></span>
<span class="line"><span>2. 消息包含加密的会话信息（Session Ticket）</span></span>
<span class="line"><span>3. 客户端保存该 Ticket</span></span>
<span class="line"><span>4. 下次连接时，客户端在 ClientHello 的 session_ticket 扩展中携带 Ticket</span></span>
<span class="line"><span>5. 服务器解密 Ticket，恢复会话，无需本地存储</span></span>
<span class="line"><span>6. 恢复握手仅需 1-RTT</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>优势</strong>：</p><ul><li>服务器无需存储会话状态（无状态）</li><li>适合多服务器部署</li><li>Ticket 加密密钥可定期轮换</li></ul><h3 id="session-id-与-session-ticket-对比" tabindex="-1"><a class="header-anchor" href="#session-id-与-session-ticket-对比"><span>Session ID 与 Session Ticket 对比</span></a></h3><table><thead><tr><th>特性</th><th>Session ID</th><th>Session Ticket</th></tr></thead><tbody><tr><td>存储位置</td><td>服务器端</td><td>客户端端</td></tr><tr><td>服务器开销</td><td>大（需存储所有会话）</td><td>小（仅存加密密钥）</td></tr><tr><td>多服务器支持</td><td>需要共享缓存</td><td>天然支持</td></tr><tr><td>安全性</td><td>服务器控制</td><td>依赖 Ticket 加密密钥</td></tr><tr><td>前向保密</td><td>取决于实现</td><td>取决于密钥轮换</td></tr><tr><td>客户端支持</td><td>广泛</td><td>广泛</td></tr></tbody></table><h3 id="nginx-session-恢复配置" tabindex="-1"><a class="header-anchor" href="#nginx-session-恢复配置"><span>Nginx Session 恢复配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">    /etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Session Cache 配置</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 语法：ssl_session_cache off | none | [builtin[:size]] [shared:name:size]</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_cache </span><span style="color:#ABB2BF;">shared:SSL:10m;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Session 超时时间</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_timeout </span><span style="color:#D19A66;">1d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Session Ticket 配置</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_tickets </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Session Ticket 密钥文件（多服务器需共享同一密钥）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ssl_session_ticket_key /etc/nginx/ssl/ticket.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 禁用 Session Ticket（某些安全合规要求）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ssl_session_tickets off;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">Session Ticket 密钥管理</p><p>如果使用多台 Nginx 服务器，必须确保所有服务器使用相同的 Session Ticket 密钥，否则客户端的 Ticket 在其他服务器上无法解密。</p><p>密钥轮换策略：</p><ul><li>定期生成新密钥</li><li>同时保留旧密钥用于解密（滚动更新）</li><li>旧密钥超过 <code>ssl_session_timeout</code> 后可删除</li></ul><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 生成 Session Ticket 密钥（80 字节随机数）</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> rand</span><span style="color:#D19A66;"> 80</span><span style="color:#ABB2BF;"> &gt; </span><span style="color:#98C379;">/etc/nginx/ssl/ticket.key</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div></div><h3 id="session-cache-共享-多服务器" tabindex="-1"><a class="header-anchor" href="#session-cache-共享-多服务器"><span>Session Cache 共享（多服务器）</span></a></h3><p>对于使用 Session ID 的多服务器环境，需要实现缓存共享：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 所有服务器使用相同的共享缓存名称和大小</span></span>
<span class="line"><span style="color:#C678DD;">ssl_session_cache </span><span style="color:#ABB2BF;">shared:SSL:10m;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 对于大规模部署，可以考虑使用 memcached 共享</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 需要第三方模块：ngx_http_ssl_session_fetch_module</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="tls-握手性能分析" tabindex="-1"><a class="header-anchor" href="#tls-握手性能分析"><span>TLS 握手性能分析</span></a></h2><h3 id="握手开销对比" tabindex="-1"><a class="header-anchor" href="#握手开销对比"><span>握手开销对比</span></a></h3><table><thead><tr><th>握手类型</th><th>RTT</th><th>CPU 开销</th><th>适用场景</th></tr></thead><tbody><tr><td>TLS 1.2 完整握手</td><td>2</td><td>高</td><td>首次连接</td></tr><tr><td>TLS 1.2 Session 恢复</td><td>1</td><td>低</td><td>重复连接</td></tr><tr><td>TLS 1.3 完整握手</td><td>1</td><td>中</td><td>首次连接</td></tr><tr><td>TLS 1.3 0-RTT</td><td>0</td><td>低</td><td>恢复连接</td></tr></tbody></table><h3 id="密钥交换性能对比" tabindex="-1"><a class="header-anchor" href="#密钥交换性能对比"><span>密钥交换性能对比</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 在服务器上测试各密钥交换算法的性能</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># RSA 2048 签名/验证</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> speed</span><span style="color:#98C379;"> rsa2048</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># RSA 2048 sign:   ~1000 次/秒</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># RSA 2048 verify: ~30000 次/秒</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ECDSA P-256 签名/验证</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> speed</span><span style="color:#98C379;"> ecdsap256</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ECDSA P-256 sign:   ~8000 次/秒</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ECDSA P-256 verify: ~3000 次/秒</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ECDH X25519 密钥交换</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> speed</span><span style="color:#98C379;"> ecdhx25519</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ECDH X25519: ~15000 次/秒</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="优化-nginx-tls-性能" tabindex="-1"><a class="header-anchor" href="#优化-nginx-tls-性能"><span>优化 Nginx TLS 性能</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 1. 使用 TLS 1.3（1-RTT 握手）</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 2. 启用 OCSP Stapling（减少证书验证延迟）</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_stapling </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_stapling_verify </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    resolver </span><span style="color:#D19A66;">8.8.8.8</span><span style="color:#D19A66;"> 8.8.4.4</span><span style="color:#ABB2BF;"> valid=300s;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 3. Session 恢复</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_cache </span><span style="color:#ABB2BF;">shared:SSL:10m;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_timeout </span><span style="color:#D19A66;">1d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_tickets </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 4. 使用高效密码套件</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_prefer_server_ciphers </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 5. 优化缓冲区</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_buffer_size </span><span style="color:#D19A66;">4k</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 6. 启用 HTTP/2（减少连接数）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # listen 443 ssl http2;  # 旧语法</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container info"><p class="hint-container-title">ssl_buffer_size</p><p><code>ssl_buffer_size</code> 控制 TLS 记录层缓冲区大小，默认 16k。对于低延迟场景（如 API），设置为 4k 可以减少首字节时间（TTFB），但会增加 CPU 开销和记录层数。参考：<a href="https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_buffer_size" target="_blank" rel="noopener noreferrer">https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_buffer_size</a></p></div><hr><h2 id="tls-握手抓包分析" tabindex="-1"><a class="header-anchor" href="#tls-握手抓包分析"><span>TLS 握手抓包分析</span></a></h2><p>使用 <code>tcpdump</code> 和 <code>tshark</code> 抓取 TLS 握手数据包：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 抓取 HTTPS 流量</span></span>
<span class="line"><span style="color:#61AFEF;">tcpdump</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> eth0</span><span style="color:#D19A66;"> -w</span><span style="color:#98C379;"> tls_handshake.pcap</span><span style="color:#98C379;"> port</span><span style="color:#D19A66;"> 443</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 tshark 分析 TLS 握手</span></span>
<span class="line"><span style="color:#61AFEF;">tshark</span><span style="color:#D19A66;"> -r</span><span style="color:#98C379;"> tls_handshake.pcap</span><span style="color:#D19A66;"> -Y</span><span style="color:#98C379;"> &quot;tls.handshake.type&quot;</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#D19A66;">  -T</span><span style="color:#98C379;"> fields</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> tls.handshake.type</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> ip.src</span><span style="color:#D19A66;"> -e</span><span style="color:#98C379;"> ip.dst</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># TLS 握手类型码</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1  = ClientHello</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2  = ServerHello</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 11 = Certificate</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 12 = ServerKeyExchange</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 14 = ServerHelloDone</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 16 = ClientKeyExchange</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 20 = Finished</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="使用-openssl-s-client-调试" tabindex="-1"><a class="header-anchor" href="#使用-openssl-s-client-调试"><span>使用 openssl s_client 调试</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 TLS 1.2 连接</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_2</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 TLS 1.3 连接</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看证书链</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -showcerts</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 指定 SNI</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -servername</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看协商的密码套件</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_3</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> &quot;Cipher&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试特定密码套件</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -cipher</span><span style="color:#98C379;"> ECDHE-RSA-AES128-GCM-SHA256</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 OCSP Stapling</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -status</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="使用-nmap-扫描-tls-配置" tabindex="-1"><a class="header-anchor" href="#使用-nmap-扫描-tls-配置"><span>使用 nmap 扫描 TLS 配置</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 扫描支持的 TLS 版本</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-enum-ciphers</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 扫描证书信息</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-cert</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检测 Heartbleed 漏洞</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-heartbleed</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="tls-1-2-与-tls-1-3-握手对比总结" tabindex="-1"><a class="header-anchor" href="#tls-1-2-与-tls-1-3-握手对比总结"><span>TLS 1.2 与 TLS 1.3 握手对比总结</span></a></h2><table><thead><tr><th>对比项</th><th>TLS 1.2</th><th>TLS 1.3</th></tr></thead><tbody><tr><td>完整握手 RTT</td><td>2</td><td>1</td></tr><tr><td>恢复握手 RTT</td><td>1</td><td>0 (0-RTT)</td></tr><tr><td>密钥交换</td><td>RSA/DHE/ECDHE</td><td>仅 ECDHE</td></tr><tr><td>认证算法</td><td>RSA/ECDSA</td><td>RSA/ECDSA</td></tr><tr><td>对称加密</td><td>CBC/GCM/CCM</td><td>仅 AEAD</td></tr><tr><td>密码套件数量</td><td>300+</td><td>5</td></tr><tr><td>前向保密</td><td>可选</td><td>强制</td></tr><tr><td>降级保护</td><td>可选（RFC 7507）</td><td>内置</td></tr><tr><td>加密握手消息</td><td>仅 Finished 之后</td><td>ServerHello 之后</td></tr><tr><td>Session 恢复</td><td>Session ID/Ticket</td><td>PSK + 0-RTT</td></tr></tbody></table><hr><h2 id="实战-完整的-nginx-tls-配置" tabindex="-1"><a class="header-anchor" href="#实战-完整的-nginx-tls-配置"><span>实战：完整的 Nginx TLS 配置</span></a></h2><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://nginx.org/en/docs/http/ngx_http_ssl_module.html</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://wiki.mozilla.org/Security/Server_Side_TLS</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#ABB2BF;">[::]:443 ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com www.example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 证书配置 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">    /etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 协议版本 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 密码套件 =====</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # TLS 1.2 密码套件</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_prefer_server_ciphers </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== ECDHE 曲线 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ecdh_curve </span><span style="color:#ABB2BF;">X25519:secp256r1:secp384r1;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== DH 参数 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_dhparam </span><span style="color:#ABB2BF;">/etc/nginx/ssl/dhparam.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== Session 恢复 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_cache </span><span style="color:#ABB2BF;">shared:SSL:10m;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_timeout </span><span style="color:#D19A66;">1d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_tickets </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ssl_session_ticket_key /etc/nginx/ssl/ticket.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== OCSP Stapling =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_stapling </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_stapling_verify </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_trusted_certificate </span><span style="color:#ABB2BF;">/etc/nginx/ssl/chain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    resolver </span><span style="color:#D19A66;">8.8.8.8</span><span style="color:#D19A66;"> 8.8.4.4</span><span style="color:#ABB2BF;"> valid=300s;</span></span>
<span class="line"><span style="color:#C678DD;">    resolver_timeout </span><span style="color:#D19A66;">5s</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 性能优化 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_buffer_size </span><span style="color:#D19A66;">4k</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 0-RTT (TLS 1.3) =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_early_data </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_pass </span><span style="color:#ABB2BF;">http://backend;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_set_header </span><span style="color:#ABB2BF;">Host $</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_set_header </span><span style="color:#ABB2BF;">X-Real-IP $</span><span style="color:#E06C75;">remote_addr</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_set_header </span><span style="color:#ABB2BF;">X-Forwarded-For $</span><span style="color:#E06C75;">proxy_add_x_forwarded_for</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_set_header </span><span style="color:#ABB2BF;">X-Forwarded-Proto $</span><span style="color:#E06C75;">scheme</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># HTTP → HTTPS 重定向</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#ABB2BF;">[::]:80;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com www.example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#D19A66;"> 301</span><span style="color:#ABB2BF;"> https://$</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">request_uri</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证配置：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 检查 Nginx 配置语法</span></span>
<span class="line"><span style="color:#61AFEF;">nginx</span><span style="color:#D19A66;"> -t</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 重新加载配置</span></span>
<span class="line"><span style="color:#61AFEF;">nginx</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> reload</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 验证 TLS 配置</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_3</span><span style="color:#ABB2BF;"> 2&gt;&amp;1 | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> &quot;Protocol|Cipher|Session&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在线检测</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://www.ssllabs.com/ssltest/</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="常见问题排查" tabindex="-1"><a class="header-anchor" href="#常见问题排查"><span>常见问题排查</span></a></h2><h3 id="证书链不完整" tabindex="-1"><a class="header-anchor" href="#证书链不完整"><span>证书链不完整</span></a></h3><p><strong>症状</strong>：浏览器显示证书不可信，但 curl 可以正常访问</p><p><strong>原因</strong>：Nginx 未配置中间证书，部分客户端无法构建完整信任链</p><p><strong>解决方案</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 检查证书链是否完整</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -showcerts</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 确保使用 fullchain.pem 而非 cert.pem</span></span>
<span class="line"><span style="color:#61AFEF;">ssl_certificate</span><span style="color:#98C379;"> /etc/letsencrypt/live/example.com/fullchain.pem</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 而不是</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ssl_certificate /etc/letsencrypt/live/example.com/cert.pem;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="协议版本不匹配" tabindex="-1"><a class="header-anchor" href="#协议版本不匹配"><span>协议版本不匹配</span></a></h3><p><strong>症状</strong>：客户端无法建立 TLS 连接</p><p><strong>排查</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 逐一测试各 TLS 版本</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_1</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_2</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_3</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查 Nginx 配置</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> ssl_protocols</span><span style="color:#98C379;"> /etc/nginx/nginx.conf</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="密码套件不匹配" tabindex="-1"><a class="header-anchor" href="#密码套件不匹配"><span>密码套件不匹配</span></a></h3><p><strong>症状</strong>：SSL握手失败，错误日志显示 &quot;no shared cipher&quot;</p><p><strong>排查</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 列出服务器支持的密码套件</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> ciphers</span><span style="color:#D19A66;"> -v</span><span style="color:#98C379;"> &#39;ECDHE-RSA-AES128-GCM-SHA256&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查 Nginx 配置的密码套件</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#98C379;"> ssl_ciphers</span><span style="color:#98C379;"> /etc/nginx/nginx.conf</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用特定密码套件测试连接</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#D19A66;">  -cipher</span><span style="color:#98C379;"> ECDHE-RSA-AES128-GCM-SHA256</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="sni-问题" tabindex="-1"><a class="header-anchor" href="#sni-问题"><span>SNI 问题</span></a></h3><p><strong>症状</strong>：多个 HTTPS 虚拟主机，访问非默认主机返回错误证书</p><p><strong>原因</strong>：客户端未发送 SNI（Server Name Indication），服务器返回默认虚拟主机的证书</p><p><strong>解决方案</strong>：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 确保每个 server 块有正确的 server_name</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">site1.example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">/etc/nginx/ssl/site1.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/site1.key;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">site2.example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">/etc/nginx/ssl/site2.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/site2.key;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 SNI</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#D19A66;">  -servername</span><span style="color:#98C379;"> site1.example.com</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读"><span>延伸阅读</span></a></h2><ul><li><a href="https://tools.ietf.org/html/rfc5246" target="_blank" rel="noopener noreferrer">RFC 5246 - TLS 1.2</a></li><li><a href="https://tools.ietf.org/html/rfc8446" target="_blank" rel="noopener noreferrer">RFC 8446 - TLS 1.3</a></li><li><a href="https://tools.ietf.org/html/rfc8996" target="_blank" rel="noopener noreferrer">RFC 8996 - Deprecating TLS 1.0 and 1.1</a></li><li><a href="https://ssl-config.mozilla.org/" target="_blank" rel="noopener noreferrer">Mozilla SSL Configuration Generator</a></li><li><a href="https://nginx.org/en/docs/http/ngx_http_ssl_module.html" target="_blank" rel="noopener noreferrer">Nginx SSL Module 官方文档</a></li><li><a href="https://www.openssl.org/docs/" target="_blank" rel="noopener noreferrer">OpenSSL 官方文档</a></li></ul>`,82)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};